public static class Shipping
{
    // Cost in cents: base 500; +100 per FULL 1000g over the first 1000g;
    // doubled when express.
    public static int Cost(int weightG, bool express)
    {
        int total = 500;
        if (weightG > 1000)
        {
            total += ((weightG - 1000) / 1000) * 100;
        }
        if (express)
        {
            total *= 2;
        }
        return total;
    }
}

