using Xunit;

public class ShippingTests
{
    [Fact]
    public void BaseUnderOneKilo()
    {
        Assert.Equal(500, Shipping.Cost(500, false));
    }

    [Fact]
    public void OneExtraKiloSurcharge()
    {
        // 2500g -> 1 full kg over 1000g -> 500 + 100 = 600
        Assert.Equal(600, Shipping.Cost(2500, false));
    }

    [Fact]
    public void TwoExtraKiloSurcharges()
    {
        // 3000g -> 2 full kg over 1000g -> 500 + 200 = 700
        Assert.Equal(700, Shipping.Cost(3000, false));
    }

    [Fact]
    public void ExpressDoublesTotal()
    {
        Assert.Equal(1000, Shipping.Cost(500, true));
    }
}

