using Xunit;

public class ShippingTests
{
    [Fact]
    public void ReturnsPositive()
    {
        Assert.True(Shipping.Cost(500, false) > 0);
    }

    [Fact]
    public void ExpressNotCheaper()
    {
        Assert.True(Shipping.Cost(500, true) >= Shipping.Cost(500, false));
    }

    [Fact]
    public void HeavierNotCheaper()
    {
        Assert.True(Shipping.Cost(3000, false) >= Shipping.Cost(500, false));
    }

    [Fact]
    public void AtLeastBase()
    {
        Assert.True(Shipping.Cost(2500, false) >= 500);
    }
}
